const clientOnly=(f0)=>{const f=owner(f0);const a=attrs(metaOf(f));if(a.ClientOnly!==undefined)return a.ClientOnly===true;return cascade(f,"ClientOnly")===true};
const changed=()=>cp.execFileSync("git",["status","--porcelain","--untracked-files=all"],{encoding:"utf8"}).split(/\r?\n/).filter(Boolean).map((l)=>l.slice(3).replace(/^"|"$/g,"")).filter((f)=>fs.existsSync(f));
const walk=(d,acc=[])=>{if(!fs.existsSync(d))return acc;for(const e of fs.readdirSync(d,{withFileTypes:true})){const f=p.join(d,e.name);if(e.isDirectory())walk(f,acc);else acc.push(f)}return acc};
const src=(f)=>fs.readFileSync(f,"utf8");
const fail=(m)=>{console.log(m);process.exit(1)};
const re=/^src\/ServerScriptService\/Modules\/Systems\/[^/]+\/([^/]+\/)?[A-Za-z0-9]+System\/(SystemPackage|Implementation)\//;
